const TEXT_KEYS = new Set(['title','editor','description_text','title_text','text','button_text','testimonial_content','testimonial_name','testimonial_job','tab_title','tab_content','heading','sub_heading','before_text','highlighted_text','rotating_text','after_text','caption','prefix','suffix','inner_text','alert_title','alert_description','link_text','field_label','placeholder','item_title','item_description','ending_number_suffix']);
const tpl = $input.first().json;
const textos = {};
const cores = new Set();

function scan(obj, path) {
  for (const [k, v] of Object.entries(obj || {})) {
    if (typeof v === 'string') {
      if (TEXT_KEYS.has(k) && v.replace(/<[^>]*>/g, '').trim()) textos[path + '.' + k] = v;
      if (/^#[0-9a-f]{3,8}$/i.test(v.trim())) cores.add(v.trim().toLowerCase());
    } else if (Array.isArray(v)) {
      v.forEach((it, i) => { if (it && typeof it === 'object') scan(it, path + '.' + k + '.' + i); });
    }
  }
}
function walk(els) {
  for (const el of els || []) {
    if (el.settings) scan(el.settings, el.id);
    walk(el.elements);
  }
}
walk(tpl.elementor_data);

return [{ json: { textos, cores: [...cores], total_textos: Object.keys(textos).length } }];

