const raw = String($input.first().json.output || '');
const ia = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
const cfg = $('Normalizar Dados').first().json;
const tpl = $('Buscar Modelo Elementor').first().json;
const data = JSON.parse(JSON.stringify(tpl.elementor_data));
const textos = ia.textos || {};
const cores = Object.fromEntries(Object.entries(ia.cores || {}).map(([a, b]) => [a.toLowerCase(), b]));
const wa = cfg.whatsapp;
let aplicados = 0;

function trocaLinks(s) {
  if (!wa) return s;
  return s.replace(/(wa\.me\/)\d+/g, '$1' + wa)
          .replace(/(api\.whatsapp\.com\/send\?phone=)\d+/g, '$1' + wa)
          .replace(/(tel:\+?)\d+/g, '$1' + wa);
}
function aplicar(obj, path) {
  for (const [k, v] of Object.entries(obj || {})) {
    const chave = path + '.' + k;
    if (typeof v === 'string') {
      if (Object.prototype.hasOwnProperty.call(textos, chave)) { obj[k] = textos[chave]; aplicados++; }
      const c = cores[obj[k].trim().toLowerCase()];
      if (c) obj[k] = c;
      obj[k] = trocaLinks(obj[k]);
    } else if (Array.isArray(v)) {
      v.forEach((it, i) => { if (it && typeof it === 'object') aplicar(it, chave + '.' + i); });
    } else if (v && typeof v === 'object') {
      aplicar(v, chave);
    }
  }
}
function walk(els) {
  for (const el of els || []) {
    if (el.settings) aplicar(el.settings, el.id);
    walk(el.elements);
  }
}
walk(data);

const pageSettings = JSON.parse(JSON.stringify(tpl.page_settings || {}));
aplicar(pageSettings, 'page');

return [{ json: {
  aplicados,
  esperados: $('Extrair Textos e Cores').first().json.total_textos,
  payload: {
    titulo: ia.titulo_pagina,
    slug: ia.slug,
    status: cfg.status,
    seo_titulo: ia.seo_titulo,
    seo_descricao: ia.seo_descricao,
    elementor_data: data,
    page_settings: pageSettings
  }
} }];
